/**
 *
 *  NamedRangePasteDlg.js
 *
 *  Created on 05.06.15
 *
 */

define('spreadsheeteditor/main/app/view/NamedRangePasteDlg',[
    'common/main/lib/view/AdvancedSettingsWindow',
], function () {
    'use strict';

    SSE.Views = SSE.Views || {};

    SSE.Views.NamedRangePasteDlg =  Common.Views.AdvancedSettingsWindow.extend(_.extend({
        options: {
            alias: 'NamedRangePasteDlg',
            separator: false,
            contentWidth: 250
        },

        initialize: function (options) {
            var me = this;

            _.extend(this.options, {
                title: this.txtTitle,
                contentStyle: 'padding: 5px 0 0;',
                contentTemplate: _.template([
                    '<div class="settings-panel active">',
                        '<div class="inner-content">',
                                '<table cols="1" style="width: 100%;">',
                                    '<tr>',
                                        '<td>',
                                            '<label class="input-label">', me.textNames,'</label>',
                                            '<div id="named-range-paste-list" class="range-tableview" style="width:100%; height: 169px;"></div>',
                                        '</td>',
                                    '</tr>',
                                '</table>',
                            '</div></div>'
                ].join(''))({scope: this})
            }, options);

            this.handler    = options.handler;
            this.ranges     = options.ranges || [];

            Common.Views.AdvancedSettingsWindow.prototype.initialize.call(this, this.options);
        },
        render: function () {
            Common.Views.AdvancedSettingsWindow.prototype.render.call(this);
            var me = this;

            this.rangeList = new Common.UI.ListView({
                el: $('#named-range-paste-list', this.$window),
                store: new Common.UI.DataViewStore(),
                simpleAddMode: true,
                cls: 'dbl-clickable',
                itemTemplate: _.template([
                    '<div style="pointer-events:none;">',
                        '<div id="<%= id %>" class="list-item" style="width: 100%;display:inline-block;">',
                            '<div class="listitem-icon toolbar__icon margin-right-5 <% print(isTable?"btn-menu-table":(isSlicer ? "btn-slicer" : "btn-named-range")) %>"></div>',
                            '<div class="padding-right-5" style="width:186px;"><%= Common.Utils.String.htmlEncode(name) %></div>',
                        '</div>',
                    '</div>'
                ].join('')),
                tabindex: 1
            });
            this.rangeList.store.comparator = function(item1, item2) {
                var n1 = item1.get('name').toLowerCase(),
                    n2 = item2.get('name').toLowerCase();
                if (n1==n2) return 0;
                return (n1<n2) ? -1 : 1;
            };
            this.rangeList.on('item:dblclick', _.bind(this.onDblClickFunction, this));
            this.rangeList.on('entervalue', _.bind(this.onPrimary, this));

            this.afterRender();
        },

        getFocusedComponents: function() {
            return [this.rangeList].concat(this.getFooterButtons());
        },

        getDefaultFocusableComponent: function () {
            return this.rangeList;
        },

        afterRender: function() {
            this._setDefaults();
        },

        _setDefaults: function () {
            if (this.ranges) {
                var me = this, arr = [], prev_name='';
                for (var i=0; i<this.ranges.length; i++) {
                    var name = this.ranges[i].asc_getName(true);
                    if (name !== prev_name) {
                        var type = this.ranges[i].asc_getType();
                        arr.push({
                            name: name,
                            scope: this.ranges[i].asc_getScope(),
                            range: this.ranges[i].asc_getRef(),
                            type: type,
                            isTable: type===Asc.c_oAscDefNameType.table,
                            isSlicer: type===Asc.c_oAscDefNameType.slicer
                        });
                    }
                    prev_name = name;
                }
                this.rangeList.store.reset(arr);
                this.rangeList.store.sort();
                if (this.rangeList.store.length>0)
                    this.rangeList.selectByIndex(0);
                this.rangeList.scroller.update({alwaysVisibleY: true});

                _.delay(function () {
                    me.rangeList.focus();
                }, 100, this);
            }
        },

        getSettings: function() {
            var rec = this.rangeList.getSelectedRec();
            return (rec) ? (new Asc.asc_CDefName(rec.get('name'), rec.get('range'), rec.get('scope'), rec.get('type'), undefined, undefined, undefined, true)) : null;
        },

        onPrimary: function() {
            this.handler && this.handler.call(this, 'ok', this.getSettings());
            this.close();
            return false;
        },

        onDlgBtnClick: function(event) {
            var state = event.currentTarget.attributes['result'].value;
            this.handler && this.handler.call(this, state,  (state == 'ok') ? this.getSettings() : undefined);
            this.close();
        },

        onDblClickFunction: function () {
            this.handler && this.handler.call(this, 'ok',  this.getSettings());
            this.close();
        },

        txtTitle: 'Paste Name',
        textNames: 'Named Ranges'
    }, SSE.Views.NamedRangePasteDlg || {}));
});


define('text!spreadsheeteditor/main/app/template/ParagraphSettingsAdvanced.template',[],function () { return '<div id="id-adv-paragraph-indents" class="settings-panel active">\r\n    <div class="inner-content">\r\n        <div>\r\n            <div class="padding-large" style="display: inline-block;">\r\n                <label class="input-label"><%= scope.textAlign %></label>\r\n                <div id="paragraphadv-spin-text-alignment"></div>\r\n            </div>\r\n        </div>\r\n        <div class="padding-very-small"><label class="header"><%= scope.strIndent %></label></div>\r\n        <div>\r\n            <div class="padding-large margin-right-3" style="display: inline-block;">\r\n                <label class="input-label"><%= scope.strIndentsLeftText %></label>\r\n                <div id="paragraphadv-spin-indent-left"></div>\r\n            </div><!--\r\n         --><div class="padding-large margin-right-3" style="display: inline-block;">\r\n                <label class="input-label"><%= scope.strIndentsRightText %></label>\r\n                <div id="paragraphadv-spin-indent-right"></div>\r\n            </div><!--\r\n         --><div class="padding-large" style="display: inline-block;vertical-align: top">\r\n                <div>\r\n                    <label class="input-label"><%= scope.strIndentsSpecial %></label>\r\n                </div>\r\n                <div>\r\n                    <div id="paragraphadv-spin-special" class="margin-right-3" style="display: inline-block;"></div><!--\r\n                 --><div id="paragraphadv-spin-special-by" style="display: inline-block;"></div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <div class="padding-very-small"><label class="header"><%= scope.strSpacing %></label></div>\r\n        <div>\r\n            <div class="margin-right-3" style="display: inline-block;">\r\n                <label class="input-label"><%= scope.strIndentsSpacingBefore %></label>\r\n                <div id="paragraphadv-spin-spacing-before"></div>\r\n            </div><!--\r\n         --><div class="margin-right-3" style="display: inline-block;">\r\n                <label class="input-label"><%= scope.strIndentsSpacingAfter %></label>\r\n                <div id="paragraphadv-spin-spacing-after"></div>\r\n            </div><!--\r\n         --><div style="display: inline-block;vertical-align: top">\r\n                <div>\r\n                    <label class="input-label"><%= scope.strIndentsLineSpacing %></label>\r\n                </div>\r\n                <div>\r\n                    <div id="paragraphadv-spin-line-rule" class="margin-right-3" style="display: inline-block;"></div><!--\r\n                 --><div id="paragraphadv-spin-line-height" style="display: inline-block;"></div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <div class="padding-large" style="padding-top: 16px; display: none;">\r\n            <div style="border: 1px solid #cbcbcb; width: 350px;">\r\n                <div id="paragraphadv-indent-preview" style="height: 80px; position: relative;"></div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div id="id-adv-paragraph-font" class="settings-panel">\r\n    <div class="inner-content" style="width: 100%;">\r\n        <div class="padding-very-small">\r\n            <label class="header"><%= scope.textEffects %></label>\r\n        </div>\r\n        <table cols="2" role="presentation">\r\n            <tr>\r\n                <td class="padding-small">\r\n                    <div id="paragraphadv-checkbox-strike"></div>\r\n                </td>\r\n                <td class="padding-small padding-left-40">\r\n                    <div id="paragraphadv-checkbox-subscript"></div>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class="padding-small">\r\n                    <div id="paragraphadv-checkbox-double-strike"></div>\r\n                </td>\r\n                <td class="padding-small padding-left-40">\r\n                    <div id="paragraphadv-checkbox-small-caps"></div>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td class="padding-large">\r\n                    <div id="paragraphadv-checkbox-superscript"></div>\r\n                </td>\r\n                <td class="padding-large padding-left-40">\r\n                    <div id="paragraphadv-checkbox-all-caps"></div>\r\n                </td>\r\n            </tr>\r\n        </table>\r\n        <div class="padding-very-small">\r\n            <label class="header"><%= scope.textCharacterSpacing %></label>\r\n        </div>\r\n        <div class="padding-large">\r\n            <div style="display: inline-block;">\r\n                <div id="paragraphadv-spin-spacing"></div>\r\n            </div>\r\n        </div>\r\n        <div class="doc-content-color" style="border: 1px solid #cbcbcb;">\r\n            <div id="paragraphadv-font-img" style="width: 300px; height: 80px; position: relative; margin: 0 auto;"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div id="id-adv-paragraph-tabs" class="settings-panel">\r\n    <div class="inner-content">\r\n        <div class="padding-large">\r\n            <label class="input-label"><%= scope.textDefault %></label>\r\n            <div id="paraadv-spin-default-tab"></div>\r\n\r\n        </div>\r\n        <div>\r\n            <div class="padding-large margin-right-9" style="display: inline-block;">\r\n                <label class="input-label"><%= scope.textTabPosition %></label>\r\n                <div id="paraadv-spin-tab"></div>\r\n            </div>\r\n            <div class="padding-large margin-right-9" style=" display: inline-block;">\r\n                <label class="input-label"><%= scope.textAlign %></label>\r\n                <div id="paraadv-cmb-align"></div>\r\n            </div>\r\n        </div>\r\n        <div>\r\n            <div colspan=3 class="padding-large">\r\n                <div id="paraadv-list-tabs" style="width:348px; height: 116px;"></div>\r\n            </div>\r\n        </div>\r\n        <div>\r\n            <button type="button" class="btn btn-text-default margin-right-9" id="paraadv-button-add-tab" style="width:108px; display: inline-block;"><%= scope.textSet %></button>\r\n            <button type="button" class="btn btn-text-default margin-right-9" id="paraadv-button-remove-tab" style="width:108px; display: inline-block;"><%= scope.textRemove %></button>\r\n            <button type="button" class="btn btn-text-default" id="paraadv-button-remove-all" style="width:108px;display: inline-block;"><%= scope.textRemoveAll %></button>\r\n        </div>\r\n    </div>\r\n</div>';});

