                            // '</table>',
                            // '<div class="separator horizontal padding-small"></div>',
                            // '<table cols="2" style="width: 100%;">',
                                '<tr>',
                                    '<td colspan=2 class="padding-small" style="border-top: 1px solid #cbcbcb;">',
                                    '</td>',
