define('spreadsheeteditor/main/app/view/ImageSettingsAdvanced',[
    'text!spreadsheeteditor/main/app/template/ImageSettingsAdvanced.template',
    'common/main/lib/view/AdvancedSettingsWindow',
], function (contentTemplate) {
    'use strict';

    SSE.Views.ImageSettingsAdvanced = Common.Views.AdvancedSettingsWindow.extend(_.extend({
        options: {
            contentWidth: 300,
            contentHeight: 257,
            toggleGroup: 'image-adv-settings-group',
            properties: null,
            storageName: 'sse-image-settings-adv-category'
        },

        initialize : function(options) {
            _.extend(this.options, {
                title: this.textTitle,
                items: [
                    {panelId: 'id-adv-image-rotate',     panelCaption: this.textRotation},
                    {panelId: 'id-adv-image-snap',       panelCaption: this.textSnap},
                    {panelId: 'id-adv-image-alttext',    panelCaption: this.textAlt}
                ],
                contentTemplate: _.template(contentTemplate)({
                    scope: this
                })
            }, options);
            Common.Views.AdvancedSettingsWindow.prototype.initialize.call(this, this.options);

            this._originalProps = this.options.imageProps;
            this._changedProps = null;
        },

        render: function() {
            Common.Views.AdvancedSettingsWindow.prototype.render.call(this);

            var me = this;

            // Rotation
            this.spnAngle = new Common.UI.MetricSpinner({
                el: $('#image-advanced-spin-angle'),
                step: 1,
                width: 80,
                defaultUnit : "°",
                value: '0 °',
                maxValue: 3600,
                minValue: -3600
            });

            this.chFlipHor = new Common.UI.CheckBox({
                el: $('#image-advanced-checkbox-hor'),
                labelText: this.textHorizontally
            });

            this.chFlipVert = new Common.UI.CheckBox({
                el: $('#image-advanced-checkbox-vert'),
                labelText: this.textVertically
            });

            // Snapping
            this.radioTwoCell = new Common.UI.RadioBox({
                el: $('#image-advanced-radio-twocell'),
                name: 'asc-radio-snap',
                labelText: this.textTwoCell,
                value: AscCommon.c_oAscCellAnchorType.cellanchorTwoCell
            });
            this.radioTwoCell.on('change', _.bind(this.onRadioSnapChange, this));

            this.radioOneCell = new Common.UI.RadioBox({
                el: $('#image-advanced-radio-onecell'),
                name: 'asc-radio-snap',
                labelText: this.textOneCell,
                value: AscCommon.c_oAscCellAnchorType.cellanchorOneCell
            });
            this.radioOneCell.on('change', _.bind(this.onRadioSnapChange, this));

            this.radioAbsolute = new Common.UI.RadioBox({
                el: $('#image-advanced-radio-absolute'),
                name: 'asc-radio-snap',
                labelText: this.textAbsolute,
                value: AscCommon.c_oAscCellAnchorType.cellanchorAbsolute
            });
            this.radioAbsolute.on('change', _.bind(this.onRadioSnapChange, this));

            // Alt Text

            this.inputAltTitle = new Common.UI.InputField({
                el          : $('#image-advanced-alt-title'),
                allowBlank  : true,
                validateOnBlur: false,
                style       : 'width: 100%;'
            }).on('changed:after', function() {
                me.isAltTitleChanged = true;
            });

            this.textareaAltDescription = this.$window.find('textarea');
            this.textareaAltDescription.keydown(function (event) {
                if (event.keyCode == Common.UI.Keys.RETURN) {
                    event.stopPropagation();
                }
                me.isAltDescChanged = true;
            });

            this.afterRender();
        },

        getFocusedComponents: function() {
            return this.btnsCategory.concat([
                this.spnAngle, this.chFlipHor, this.chFlipVert, // 0 tab
                this.radioTwoCell, this.radioOneCell, this.radioAbsolute, // 1 tab
                this.inputAltTitle, this.textareaAltDescription  // 2 tab
            ]).concat(this.getFooterButtons());
        },

        onCategoryClick: function(btn, index) {
            Common.Views.AdvancedSettingsWindow.prototype.onCategoryClick.call(this, btn, index);

            var me = this;
            setTimeout(function(){
                switch (index) {
                    case 0:
                        me.spnAngle.focus();
                        break;
                    case 1:
                        me.radioTwoCell.focus();
                        break;
                    case 2:
                        me.inputAltTitle.focus();
                        break;
                }
            }, 10);
        },

        onRadioSnapChange: function(field, newValue, eOpts) {
            if (newValue && this._changedProps) {
                this._changedProps.asc_putAnchor(field.options.value);
            }
        },

        afterRender: function() {
            this._setDefaults(this._originalProps);
            if (this.storageName) {
                var value = Common.localStorage.getItem(this.storageName);
                this.setActiveCategory((value!==null) ? parseInt(value) : 0);
            }
        },

        _setDefaults: function(props) {
            if (props ){
                var value = props.asc_getTitle();
                this.inputAltTitle.setValue(value ? value : '');

                value = props.asc_getDescription();
                this.textareaAltDescription.val(value ? value : '');

                value = props.asc_getRot();
                this.spnAngle.setValue((value==undefined || value===null) ? '' : Math.floor(value*180/3.14159265358979+0.5), true);
                this.chFlipHor.setValue(props.asc_getFlipH());
                this.chFlipVert.setValue(props.asc_getFlipV());

                value = props.asc_getAnchor();
                switch (value) {
                    case AscCommon.c_oAscCellAnchorType.cellanchorTwoCell:
                        this.radioTwoCell.setValue(true, true);
                        break;
                    case AscCommon.c_oAscCellAnchorType.cellanchorOneCell:
                        this.radioOneCell.setValue(true, true);
                        break;
                    case AscCommon.c_oAscCellAnchorType.cellanchorAbsolute:
                        this.radioAbsolute.setValue(true, true);
                        break;
                }

                var pluginGuid = props.asc_getPluginGuid();
                this.btnsCategory[0].setVisible(pluginGuid === null || pluginGuid === undefined); // Rotation

                this._changedProps = new Asc.asc_CImgProperty();
            }
        },

        getSettings: function() {
            if (this.isAltTitleChanged)
                this._changedProps.asc_putTitle(this.inputAltTitle.getValue());

            if (this.isAltDescChanged)
                this._changedProps.asc_putDescription(this.textareaAltDescription.val());

            this._changedProps.asc_putRot(this.spnAngle.getNumberValue() * 3.14159265358979 / 180);
            this._changedProps.asc_putFlipH(this.chFlipHor.getValue()=='checked');
            this._changedProps.asc_putFlipV(this.chFlipVert.getValue()=='checked');

            return { imageProps: this._changedProps} ;
        },

        textTitle:      'Image - Advanced Settings',
        textAlt: 'Alternative Text',
        textAltTitle: 'Title',
        textAltDescription: 'Description',
        textAltTip: 'The alternative text-based representation of the visual object information, which will be read to the people with vision or cognitive impairments to help them better understand what information there is in the image, autoshape, chart or table.',
        textRotation: 'Rotation',
        textAngle: 'Angle',
        textFlipped: 'Flipped',
        textHorizontally: 'Horizontally',
        textVertically: 'Vertically',
        textSnap: 'Cell Snapping',
        textAbsolute: 'Don\'t move or size with cells',
        textOneCell: 'Move but don\'t size with cells',
        textTwoCell: 'Move and size with cells'

    }, SSE.Views.ImageSettingsAdvanced || {}));
});

define('text!spreadsheeteditor/main/app/template/SlicerSettingsAdvanced.template',[],function () { return '<div id="id-adv-slicer-style" class="settings-panel active">\n    <div class="inner-content">\n        <div>\n            <div class="padding-small" style="display: inline-block;">\n                <label class="input-label"><%= scope.textHeader %></label>\n                <div id="sliceradv-text-header"></div>\n            </div>\n        </div>\n        <div class="padding-large" id="sliceradv-checkbox-header"></div>\n        <div class="padding-very-small"><label class="header"><%= scope.strStyle %></label></div>\n        <div class="padding-large">\n            <div id="sliceradv-btn-style" style="width: 100%;height: 52px;"></div>\n        </div>\n        <div class="padding-very-small"><label class="header"><%= scope.strSize %></label></div>\n        <div class="padding-large">\n            <div class="margin-right-5" style="display: inline-block;">\n                <label class="input-label"><%= scope.strWidth %></label>\n                <div id="sliceradv-spin-width"></div>\n            </div>\n            <div id="sliceradv-button-ratio" class="margin-right-5"></div>\n            <div style="display: inline-block;">\n                <label class="input-label"><%= scope.strHeight %></label>\n                <div id="sliceradv-spin-height"></div>\n            </div>\n        </div>\n        <div class="padding-very-small"><label class="header"><%= scope.strButtons %></label></div>\n        <div>\n            <div class="margin-right-5" style="display: inline-block;">\n                <label class="input-label"><%= scope.strColumns %></label>\n                <div id="sliceradv-spin-columns"></div>\n            </div>\n            <div style="display: inline-block;">\n                <label class="input-label"><%= scope.strHeight %></label>\n                <div id="sliceradv-spin-col-height"></div>\n            </div>\n        </div>\n    </div>\n</div>\n<div id="id-adv-slicer-sorting" class="settings-panel">\n    <div class="inner-content" style="width: 100%;">\n        <div class="padding-small">\n            <label class="header"><%= scope.textSort %></label>\n        </div>\n        <div class="padding-large">\n            <div style="display: inline-block;" role="radiogroup">\n                <div class="padding-small" id="sliceradv-radio-asc"></div>\n                <div class="padding-small" id="sliceradv-radio-desc"></div>\n            </div>\n        </div>\n        <div>\n            <div style="display: inline-block;">\n                <div class="padding-small" id="sliceradv-check-hide-nodata"></div>\n                <div class="padding-small" id="sliceradv-check-indicate-nodata"></div>\n                <div class="padding-small" id="sliceradv-check-show-nodata-last"></div>\n                <!--<div class="padding-small" id="sliceradv-check-show-deleted"></div>-->\n            </div>\n        </div>\n    </div>\n</div>\n<div id="id-adv-slicer-references" class="settings-panel">\n    <div class="inner-content">\n        <div class="padding-large">\n            <label class="header" style="display: block;"><%= scope.textSourceName %></label>\n            <label class="input-label" id="sliceradv-lbl-source"></label>\n        </div>\n        <div class="padding-large">\n            <label class="header" style="display: block;"><%= scope.textFormulaName %></label>\n            <label class="input-label" id="sliceradv-lbl-formula"></label>\n        </div>\n        <div class="padding-large">\n            <label class="header"><%= scope.textName %></label>\n            <div id="sliceradv-text-name"></div>\n        </div>\n    </div>\n</div>\n<div id="id-adv-slicer-snap" class="settings-panel">\n    <div class="inner-content">\n        <table cols="1" role="presentation">\n            <tr>\n                <td class="padding-small" role="radiogroup" aria-owns="slicer-advanced-radio-onecell slicer-advanced-radio-absolute">\n                    <div id="slicer-advanced-radio-twocell"></div>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small">\n                    <div id="slicer-advanced-radio-onecell"></div>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small">\n                    <div id="slicer-advanced-radio-absolute"></div>\n                </td>\n            </tr>\n        </table>\n    </div>\n</div>\n<div id="id-adv-slicer-alttext" class="settings-panel">\n    <div class="inner-content">\n        <table cols="1" width="100%" role="presentation">\n            <tr>\n                <td class="padding-large">\n                    <label class="header"><%= scope.textAltTitle %></label>\n                    <div id="sliceradv-alt-title"></div>\n                </td>\n            </tr>\n            <tr>\n                <td>\n                    <label class="header"><%= scope.textAltDescription %></label>\n                    <textarea id="sliceradv-alt-description" class="form-control" style="width: 100%; height: 120px;"></textarea>\n                </td>\n            </tr>\n            <tr>\n                <td>\n                    <label><%= scope.textAltTip %></label>\n                </td>\n            </tr>\n        </table>\n    </div>\n</div>';});

